from shapely import wkb
import matplotlib.pyplot as plt
import geopandas as gpd

# List of WKB data (as hex strings)
wkb_data_list = [
        "",
        "",
        "010500000001000000010200000002000000B8048DBD688258402C0E23F8FEC53340B80CCD1F78825840F37D6C4002C63340",
        "",
        ""# Example WKB data 1
    # Example WKB data 2 (replace with your actual data)
]

# Step 1: Decode each WKB data into Shapely geometries
geometries = [wkb.loads(bytes.fromhex(data)) for data in wkb_data_list]

# Step 2: Create a GeoDataFrame from the list of geometries
gdf = gpd.GeoDataFrame(geometry=geometries)

# Step 3: Plot using GeoPandas (this also supports plotting with basemaps if needed)
gdf.plot(marker='o', color='blue', figsize=(10, 10))
plt.title("Visualization of Multiple WKB Geometries")
plt.xlabel("Longitude")
plt.ylabel("Latitude")
plt.grid(True)
plt.show()
